const input = $json.body ?? $json;
const source = input.transaction ?? input;
const strategy = String(source.exit_strategy ?? source.disposition_strategy ?? '').toLowerCase().trim();
const allowedStrategies = ['assignment','novation','double_close','wholetail','resale','hold','review'];
const status = String(source.transaction_status ?? source.status ?? 'transaction_pending').toLowerCase().trim();
const allowedStatuses = ['transaction_pending','title_review','disclosures_pending','assignment_prepared','assignment_executed','novation_pending','novation_executed','double_close_funding_pending','double_close_ready','closing_scheduled','closed','failed','cancelled'];
const identity = { candidate_key: source.candidate_key ?? null, normalized_identity_key: source.normalized_identity_key ?? null, lead_id: source.leadId ?? source.lead_id ?? null, deal_id: source.dealId ?? source.deal_id ?? null, property_id: source.propertyId ?? source.property_id ?? null, external_id: source.external_id ?? null, parcel_id: source.parcel_id ?? null };
const selectedBuyer = source.selected_buyer ?? source.selectedBuyer ?? null;
const contract = { contract_id: source.executed_contract_id ?? source.contract_id ?? null, contract_price: Number(source.contract_price ?? source.purchase_price ?? NaN) };
const economics = { assignment_fee: Number(source.assignment_fee ?? NaN), buyer_purchase_price: Number(source.buyer_purchase_price ?? source.buyer_price ?? NaN) };
const validStrategy = allowedStrategies.includes(strategy);
const validStatus = allowedStatuses.includes(status);
const requiresBuyer = ['assignment','novation','double_close'].includes(strategy);
const missing = [];
if (!identity.candidate_key && !identity.normalized_identity_key && !identity.parcel_id && !identity.property_id) missing.push('property_identity');
if (!contract.contract_id) missing.push('executed_contract_id');
if (!Number.isFinite(contract.contract_price)) missing.push('contract_price');
if (!validStrategy) missing.push('supported_exit_strategy');
if (!validStatus) missing.push('supported_transaction_status');
if (requiresBuyer && !selectedBuyer) missing.push('selected_buyer');
if (strategy === 'assignment' && !Number.isFinite(economics.assignment_fee)) missing.push('assignment_fee');
if (strategy === 'assignment' && !Number.isFinite(economics.buyer_purchase_price)) missing.push('buyer_purchase_price');
const transitionMap = { transaction_pending:['title_review','disclosures_pending','assignment_prepared','novation_pending','double_close_funding_pending','closing_scheduled','failed','cancelled'], title_review:['disclosures_pending','assignment_prepared','novation_pending','double_close_funding_pending','failed','cancelled'], disclosures_pending:['assignment_prepared','novation_pending','double_close_funding_pending','closing_scheduled','failed','cancelled'], assignment_prepared:['assignment_executed','failed','cancelled'], assignment_executed:['closing_scheduled','closed','failed','cancelled'], novation_pending:['novation_executed','failed','cancelled'], novation_executed:['closing_scheduled','closed','failed','cancelled'], double_close_funding_pending:['double_close_ready','failed','cancelled'], double_close_ready:['closing_scheduled','failed','cancelled'], closing_scheduled:['closed','failed','cancelled'], closed:[], failed:[], cancelled:[] };
const prior = String(source.prior_transaction_status ?? '').toLowerCase().trim();
const transitionValid = !prior || (transitionMap[prior] ?? []).includes(status) || prior === status;
const readiness = missing.length ? 'needs_data' : (!transitionValid ? 'invalid_transition' : (status === 'closed' ? 'closed' : 'ready'));
const nextAction = readiness === 'needs_data' ? 'Collect missing transaction data before advancing.' : readiness === 'invalid_transition' ? 'Review the prior transaction state and use a supported transition.' : status === 'closed' ? 'Record closing outcome and move to post-close reporting.' : status === 'assignment_executed' || status === 'novation_executed' || status === 'double_close_ready' || status === 'closing_scheduled' ? 'Coordinate closing through the authorized closing/title process.' : status === 'transaction_pending' ? 'Begin title/disclosure and transaction readiness review.' : 'Advance the transaction through the next authorized state.';
const transactionPackage = { identity, exit_strategy: strategy, transaction_status: status, prior_transaction_status: prior || null, selected_buyer: selectedBuyer, backup_buyer: source.backup_buyer ?? null, contract, economics, missing_requirements: missing, transition_valid: transitionValid };
return [{ json: { ok: readiness === 'ready' || readiness === 'closed', readiness, transaction_status: status, exit_strategy: strategy, identity, selected_buyer: selectedBuyer, backup_buyer: source.backup_buyer ?? null, contract, economics, missing_requirements: missing, transition_valid: transitionValid, transaction_package: transactionPackage, closing_ready: ['closing_scheduled','closed'].includes(status) && missing.length === 0 && transitionValid, next_action: nextAction, policy: { no_legal_validation: true, no_title_clearance_claim: true, no_funding_verification: true, no_closing_execution: true } } }];

const input=$input.first().json;
try {
  const base=$env.INSULA_CRM_BASE_URL, apiKey=$env.INSULA_CRM_API_KEY;
  const leadId=Number(input.insulaLeadId||input.leadId||input.lead_id||input.property_identity?.lead_id||input.identity?.lead_id||input.transaction_ids?.lead_id||input.crm_update?.lead_id||0);
  if(base&&apiKey&&leadId){
    const payload=input.transaction_tracking||input.buyer_matching||input.buyer_disposition||input.exit_strategy_gate||input;
    await this.helpers.httpRequest({
      method:'POST',url:base+'/api/v1/activities',
      headers:{'X-API-Key':apiKey,'Content-Type':'application/json',
        'Idempotency-Key':'acquisition:transaction-tracking:'+leadId+':'+String(input.candidate_key||input.normalized_identity_key||input.external_id||input.dealId||input.deal_id||'record')+':v1'},
      body:{lead_id:leadId,type:'stage_change',
        subject:"Transaction tracking state updated",
        body:'Workflow event: transaction-tracking. Status/readiness: '+String(payload.status||payload.readiness||payload.current_status||payload.closeout_status||payload.post_close_status||payload.transaction_status||'updated')+'. Next action: '+String(payload.next_action||input.next_action||'review').slice(0,500)},
      json:true
    });
  }
}catch(error){ console.log('InsulaCRM activity sync failed:',error.message); }
return [{json:input}];
